package com.example.pgck2;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class StatsReportTest {
    private Map<String,StatsReport.Movie> catalog(){Map<String,StatsReport.Movie> data=new LinkedHashMap<>();data.put("a",new StatsReport.Movie("a","Alpha",Arrays.asList("Hành động","Hành động","Hài")));data.put("b",new StatsReport.Movie("b","Beta",Collections.singletonList("Hài")));data.put("c",new StatsReport.Movie("c","Chưa xem",Collections.emptyList()));return data;}
    private StatsReport.Event event(String movie,String uid,String kind,long time){return new StatsReport.Event(movie,"Đã gỡ",uid,kind,time,Collections.singletonList("Tài liệu"));}
    private StatsReport build(List<StatsReport.Event> views,List<StatsReport.Event> changes,List<StatsReport.Event> active,String genre){return new StatsReport(catalog(),Arrays.asList("Hài","Hành động","Kinh dị"),views,changes,active,1,2026,Calendar.NOVEMBER,genre);}
    @Test public void utcPlusSevenMonthIncludesStartAndExcludesNextMonth(){
        long[] bounds=StatsReport.range(1,2026,Calendar.NOVEMBER);Calendar utc=Calendar.getInstance(TimeZone.getTimeZone("UTC"));utc.clear();utc.set(2026,Calendar.OCTOBER,31,17,0,0);assertEquals(utc.getTimeInMillis(),bounds[0]);
        StatsReport r=build(Arrays.asList(event("a","1","view",bounds[0]-1),event("a","1","view",bounds[0]),event("a","2","view",bounds[1]-1),event("a","3","view",bounds[1])),Collections.emptyList(),Collections.emptyList(),null);assertEquals(2,r.total.views);assertEquals(2,r.viewers.size());assertEquals(30,r.timeline.size());
    }
    @Test public void fullYearHandlesLeapDayAndSeedsAllMonths(){long[] year=StatsReport.range(2,2024,0);long[] feb=StatsReport.range(1,2024,1);StatsReport r=new StatsReport(catalog(),Collections.emptyList(),Collections.singletonList(event("a","u","view",feb[1]-1)),Collections.emptyList(),Collections.emptyList(),2,2024,0,null);assertEquals(12,r.timeline.size());assertEquals(1,r.timeline.get("2024-02").views);assertEquals(366L*24*60*60*1000,year[1]-year[0]);}
    @Test public void genreMembershipDoesNotDoubleGlobalTotalsOrDuplicateTags(){long t=StatsReport.range(1,2026,10)[0];StatsReport r=build(Arrays.asList(event("a","u","view",t),event("b","u","view",t)),Collections.emptyList(),Collections.emptyList(),null);assertEquals(2,r.total.views);assertEquals(1,r.viewers.size());assertEquals(1,r.genres.get("Hành động").movies);assertEquals(2,r.genres.get("Hài").movies);assertEquals(1,r.genres.get("Hành động").views);assertEquals(0,r.genres.get("Kinh dị").movies);}
    @Test public void lowestRankingIncludesUnwatchedCatalogMovies(){long t=StatsReport.range(1,2026,10)[0];StatsReport r=build(Collections.singletonList(event("a","u","view",t)),Collections.emptyList(),Collections.emptyList(),null);assertEquals("b",r.ranking(0,true,true).get(0).id);assertEquals("a",r.ranking(0,false,true).get(0).id);assertEquals(3,r.movies.size());}
    @Test public void currentReactionsStayIndependentOfPeriodAndHistoricalChanges(){long t=StatsReport.range(1,2026,10)[0];StatsReport r=build(Collections.emptyList(),Arrays.asList(event("a","u","like",t),event("a","u","dislike",t+1),event("a","u","none",t+2),event("a","u","like",t-1)),Collections.singletonList(event("b","v","like",t-100)),null);assertEquals(1,r.total.likes);assertEquals(1,r.total.dislikes);assertEquals(1,r.total.removals);assertEquals(1,r.total.activeLikes);assertEquals(0,r.movies.get("a").numbers.activeLikes);assertEquals("a",r.ranking(2,false,true).get(0).id);}
    @Test public void genreFilterAppliesToEveryMetricAndCatalogCount(){long t=StatsReport.range(1,2026,10)[0];StatsReport r=build(Arrays.asList(event("a","1","view",t),event("b","2","view",t)),Collections.singletonList(event("b","2","like",t)),Collections.singletonList(event("b","2","like",t)),"Hành động");assertEquals(1,r.total.movies);assertEquals(1,r.total.views);assertEquals(0,r.total.likes);assertEquals(0,r.total.activeLikes);assertEquals(1,r.genres.size());assertEquals(1,r.ranking(0,true,true).size());}
    @Test public void removedMoviePreservesSnapshotGenreWithoutInventingCatalogMovie(){long t=StatsReport.range(1,2026,10)[0];StatsReport r=build(Collections.singletonList(event("gone","u","view",t)),Collections.emptyList(),Collections.emptyList(),"Tài liệu");assertEquals(0,r.total.movies);assertEquals(1,r.total.views);assertTrue(r.movies.get("gone").removed);assertEquals(0,r.ranking(0,false,false).size());assertEquals(1,r.genres.get("Tài liệu").views);}
    @Test public void emptyDataIsZeroNotPlaceholder(){StatsReport r=build(Collections.emptyList(),Collections.emptyList(),Collections.emptyList(),null);assertEquals(0,r.total.views);assertEquals(0,r.total.likes);assertEquals(3,r.total.movies);assertEquals(0,r.genres.get("Kinh dị").views);assertEquals(1,r.genres.get(StatsReport.UNCATEGORIZED).movies);}
}
